# ------------------------- src/features/selfupdate.sh -------------------------
# ============================================================================
# features/selfupdate.sh — install as the `st` command and self-update.
#
# Downloads prefer the latest GitHub Release (with SHA-256 verification when
# sha256sum is available) and fall back to the raw main build only while no
# release exists yet. Every downloaded file must pass `bash -n` and a
# fingerprint check before it replaces anything.
# ============================================================================

readonly ST_INSTALL_PATH='/usr/local/bin/st'
readonly ST_URL_RELEASE='https://github.com/Sir-Adnan/server-tools/releases/latest/download/server-tools.sh'
readonly ST_URL_RELEASE_SUMS='https://github.com/Sir-Adnan/server-tools/releases/latest/download/SHA256SUMS'
readonly ST_URL_RAW='https://raw.githubusercontent.com/Sir-Adnan/server-tools/main/dist/server-tools.sh'

# _self_source_path — path of the running script, empty when running from a
# pipe/process substitution (`bash <(curl ...)` yields a non-reusable /dev/fd).
_self_source_path() {
  local src="${BASH_SOURCE[0]:-}"
  if [[ -f $src && -r $src ]]; then
    printf '%s' "$src"
    return 0
  fi
  return 1
}

# _self_download DEST — fetch, verify (checksum + parse + fingerprint), move.
_self_download() {
  local dest="$1" tmp="${ST_LIB_DIR}/download.$$" from_release=0
  if ! has_cmd curl; then
    log_error "curl is required to download ServerTools."
    return 1
  fi

  if curl -fsSL --max-time 60 "$ST_URL_RELEASE" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    from_release=1
  elif ! curl -fsSL --max-time 60 "$ST_URL_RAW" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    rm -f "$tmp"
    log_error "Download failed (release and raw fallback) — see the log."
    return 1
  fi

  if ((from_release)) && has_cmd sha256sum; then
    local sums expected actual
    sums="$(curl -fsSL --max-time 30 "$ST_URL_RELEASE_SUMS" 2>>"$ST_LOG_FILE")" || sums=''
    if [[ -z $sums ]]; then
      log_warn "SHA256SUMS could not be fetched — the release was NOT checksum-verified."
      printf '%sWarning:%s checksum file unavailable; only syntax checks were run.\n' "$C_WARN" "$C_RESET"
    fi
    if [[ -n $sums ]]; then
      expected="$(awk '/server-tools\.sh/ {print $1; exit}' <<<"$sums")"
      actual="$(sha256sum "$tmp" | awk '{print $1}')"
      if [[ -z $expected ]]; then
        rm -f "$tmp"
        log_error "SHA256SUMS has no entry for server-tools.sh — refusing an unverifiable release."
        return 1
      fi
      if [[ $expected != "$actual" ]]; then
        rm -f "$tmp"
        log_error "SHA-256 mismatch on the downloaded release — aborting."
        return 1
      fi
    fi
  fi

  if ! bash -n "$tmp" 2>>"$ST_LOG_FILE" || ! grep -q 'ST_NAME="ServerTools"' "$tmp"; then
    rm -f "$tmp"
    log_error "Downloaded file failed sanity checks — nothing was replaced."
    return 1
  fi
  mv -f "$tmp" "$dest"
}

st_self_install() {
  local src
  mkdir -p "$(dirname "$ST_INSTALL_PATH")"
  # Deliberately NOT tracked: the installed command is the tool itself, not a
  # system change — a later rollback must never delete the user's `st`.
  if src="$(_self_source_path)"; then
    cp -f "$src" "$ST_INSTALL_PATH"
  else
    printf 'Running from a pipe — downloading the current build instead.\n'
    _self_download "$ST_INSTALL_PATH" || return 1
  fi
  chmod 755 "$ST_INSTALL_PATH"
  printf '%sInstalled.%s Run %sst%s from now on; update anytime with: st --update\n' \
    "$C_OK" "$C_RESET" "$C_KEY" "$C_RESET"
  log_info "Installed to ${ST_INSTALL_PATH} (v${ST_VERSION})."
}

st_self_update() {
  local target new_ver staged="${ST_LIB_DIR}/update.$$"
  if [[ -f $ST_INSTALL_PATH ]]; then
    target="$ST_INSTALL_PATH"
  elif ! target="$(_self_source_path)"; then
    log_error "Not installed and not running from a file — use --install first."
    return 1
  fi

  # Single download: fetch once through the verifying path into a staging
  # file, read its version, and promote that exact verified file.
  _self_download "$staged" || return 1

  new_ver="$(grep -oE 'ST_VERSION="[^"]+"' "$staged" | head -n1 | cut -d'"' -f2)" || new_ver=''
  if [[ -z $new_ver ]]; then
    rm -f "$staged"
    log_error "Could not read the downloaded version — aborting."
    return 1
  fi
  if [[ $new_ver == "$ST_VERSION" ]] || ! ver_ge "$new_ver" "$ST_VERSION"; then
    # Equal, or the published build is OLDER (e.g. a raw-main fallback lagging
    # a locally newer build): never downgrade silently.
    printf 'Already up to date (v%s; published: v%s).\n' "$ST_VERSION" "$new_ver"
    rm -f "$staged"
    return 0
  fi

  mv -f "$staged" "$target"
  chmod 755 "$target"
  printf '%sUpdated:%s v%s -> v%s (%s)\n' "$C_OK" "$C_RESET" "$ST_VERSION" "$new_ver" "$target"
  log_info "Self-updated: v${ST_VERSION} -> v${new_ver}."
}

# ------------------------- src/features/diagnose.sh -------------------------
# ============================================================================
# features/diagnose.sh — read-only data-path diagnostics (`st --diagnose`).
#
# Answers the question tuning reports keep raising — "why is this core hot /
# why did CPU go up?" — with measurements instead of claims: per-CPU
# softirq/system/steal over a short sample, softnet backlog drops and budget
# squeezes, NIC queues and steering, qdisc drops, conntrack pressure, and the
# tunnel audit. No tuning is changed (missing prerequisites such as ethtool
# are installed first, per install_deps); the sample takes ~3 seconds.
# ============================================================================

readonly ST_DIAG_SAMPLE_SECS=3

# _diag_cpu_stat — "cpuN total softirq system steal" per CPU from /proc/stat.
_diag_cpu_stat() {
  awk '/^cpu[0-9]+ / {
    t = 0; for (i = 2; i <= NF; i++) t += $i
    print $1, t, $8, $4, ($9 == "" ? 0 : $9)
  }' /proc/stat
}

# _diag_softnet — "cpu processed dropped squeezed" (hex columns → decimal).
# The row index is the CPU id on modern kernels (column 13 when present).
_diag_softnet() {
  [[ -r /proc/net/softnet_stat ]] || return 0
  local -a f=()
  local idx=0 cpu
  while IFS=' ' read -ra f; do
    cpu=$idx
    ((${#f[@]} >= 13)) && [[ ${f[12]} =~ ^[0-9a-fA-F]+$ ]] && cpu=$((16#${f[12]}))
    printf '%s %s %s %s\n' "$cpu" "$((16#${f[0]}))" "$((16#${f[1]}))" "$((16#${f[2]}))"
    idx=$((idx + 1))
  done </proc/net/softnet_stat
}

# _diag_conntrack_stats — "drop early_drop insert_failed" summed over CPUs.
_diag_conntrack_stats() {
  local file=/proc/net/stat/nf_conntrack
  [[ -r $file ]] || return 0
  local -a hdr=() row=()
  local i drop=0 early=0 ins=0 first=1
  while IFS=' ' read -ra row; do
    if ((first)); then
      hdr=("${row[@]}")
      first=0
      continue
    fi
    for ((i = 0; i < ${#hdr[@]}; i++)); do
      case "${hdr[i]}" in
        drop) drop=$((drop + 16#${row[i]})) ;;
        early_drop) early=$((early + 16#${row[i]})) ;;
        insert_failed) ins=$((ins + 16#${row[i]})) ;;
      esac
    done
  done <"$file"
  printf '%s %s %s\n' "$drop" "$early" "$ins"
}

_diag_cpu_section() {
  local before after sn_before sn_after
  before="$(_diag_cpu_stat)"
  sn_before="$(_diag_softnet)"
  printf '  %sSampling %d s…%s' "$C_MUTED" "$ST_DIAG_SAMPLE_SECS" "$C_RESET"
  sleep "$ST_DIAG_SAMPLE_SECS"
  after="$(_diag_cpu_stat)"
  sn_after="$(_diag_softnet)"
  printf '\r%*s\r' 30 ''

  ui_section "CPU — where the time goes (last ${ST_DIAG_SAMPLE_SECS} s)"
  printf '    %s%-6s %8s %8s %8s %10s %8s%s\n' "$C_KEY" "CPU" "softirq" "system" "steal" "packets/s" "drops" "$C_RESET"
  local rows
  rows="$(awk -v secs="$ST_DIAG_SAMPLE_SECS" '
    FNR == 1 { file++ }
    file == 1 { t0[$1] = $2; si0[$1] = $3; sy0[$1] = $4; st0[$1] = $5; next }
    file == 2 { dt = $2 - t0[$1]; if (dt <= 0) dt = 1
                id = $1; sub(/^cpu/, "", id)
                si[id] = 100 * ($3 - si0[$1]) / dt; sy[id] = 100 * ($4 - sy0[$1]) / dt; st[id] = 100 * ($5 - st0[$1]) / dt
                cpus[id] = 1; next }
    file == 3 { p0[$1] = $2; d0[$1] = $3; next }
    file == 4 { pk[$1] = ($2 - p0[$1]) / secs; dr[$1] = $3 - d0[$1]; next }
    END { for (c in cpus) printf "%d %.1f %.1f %.1f %d %d\n", c, si[c], sy[c], st[c], pk[c], dr[c] }' \
    <(printf '%s\n' "$before") <(printf '%s\n' "$after") \
    <(printf '%s\n' "${sn_before:-x 0 0 0}") <(printf '%s\n' "${sn_after:-x 0 0 0}") | sort -n)"

  local cpu si sy st pk dr max_si=0 sum_si=0 n=0 max_st=0 hot='' drops=0
  while IFS=' ' read -r cpu si sy st pk dr; do
    [[ -n $cpu ]] || continue
    printf '    %-6s %7s%% %7s%% %7s%% %10s %8s\n' "cpu${cpu}" "$si" "$sy" "$st" "$pk" "$dr"
    n=$((n + 1))
    sum_si=$((sum_si + ${si%.*}))
    ((${si%.*} > max_si)) && {
      max_si=${si%.*}
      hot=$cpu
    }
    ((${st%.*} > max_st)) && max_st=${st%.*}
    drops=$((drops + dr))
  done <<<"$rows"

  ui_section "Verdict"
  local avg_si=0
  ((n > 0)) && avg_si=$((sum_si / n))
  if ((n > 1 && max_si >= 40 && max_si > avg_si * 2)); then
    ui_step_note err "cpu${hot} runs ${max_si}% softirq while the average is ${avg_si}% — single-core packet hot spot."
    if ((ST_P_RPS == 0)); then
      ui_step_note warn "RPS is off: enable it with  st --set rps_mode=on  then re-run Quick Optimize."
    fi
  elif ((max_si >= 20)); then
    ui_step_note ok "softirq load is spread (max ${max_si}%, average ${avg_si}%)."
  else
    ui_step_note ok "packet processing is light (max ${max_si}% softirq)."
  fi
  if ((max_st >= 10)); then
    ui_step_note warn "up to ${max_st}% steal — the hypervisor is withholding CPU; tuning cannot fix a noisy host."
  fi
  if ((drops > 0)); then
    ui_step_note err "${drops} packet(s) dropped from per-CPU backlogs during the sample — a core is saturated."
  fi
  if ((ST_P_RPS && ST_P_FWD_HEAVY && avg_si >= 25)); then
    ui_step_note warn "This forwarder spends ${avg_si}% per core in softirq with RPS on. RPS adds a cross-CPU hop per packet; compare at equal traffic:"
    printf '        st --set rps_mode=off && st --auto      (then re-check: st --diagnose)\n'
    printf '        st --set rps_cpus=1-%d && st --auto    (keep cpu0 for the NIC interrupt)\n' "$((ST_F_CPUS - 1))"
    ui_step_note idle "The biggest structural saving for a NAT relay is the nftables fast path: Network tools → f."
  fi
  return 0
}

_diag_nic_section() {
  local iface="$ST_F_IFACE" q mask rps='' xps=''
  ui_section "Uplink ${iface:-?}"
  [[ -n $iface ]] || {
    ui_step_note idle "No default route."
    return 0
  }
  ui_kv "Driver · MTU" "${ST_F_DRIVER} · ${ST_F_IFACE_MTU}"
  ui_kv "Queues" "${ST_F_RXQ} RX · ${ST_F_TXQ} TX for ${ST_F_CPUS} CPUs"
  if ((ST_F_CH_MAX > 0)); then
    ui_kv "Channels" "${ST_F_CH_CUR} in use of ${ST_F_CH_MAX} offered"
    ((ST_F_CH_CUR < ST_F_CH_MAX && ST_F_CH_CUR < ST_F_CPUS)) &&
      ui_step_note warn "the NIC offers more queue pairs than it uses — Quick Optimize raises them on virtio (nic_channels)."
  fi
  ui_kv "GRO / UDP-GRO fwd" "${ST_F_GRO:-n/a} · ${ST_F_UDPGRO:-n/a}"
  for q in /sys/class/net/"$iface"/queues/rx-*/rps_cpus; do
    [[ -r $q ]] || continue
    mask="$(cpu_mask_norm "$(cat "$q" 2>/dev/null)")"
    rps+="${rps:+ }${mask}"
  done
  for q in /sys/class/net/"$iface"/queues/tx-*/xps_cpus; do
    [[ -r $q ]] || continue
    mask="$(cpu_mask_norm "$(cat "$q" 2>/dev/null)")"
    xps+="${xps:+ }${mask}"
  done
  ui_kv "RPS masks" "${rps:-n/a} (0 = off)"
  ui_kv "XPS masks" "${xps:-n/a}"
  local irq nvec
  irq="$(policy_irq_cpus "$iface")"
  nvec="$(net_rx_irqs "$iface" | grep -c .)" || nvec=0
  ui_kv "IRQ CPUs" "${irq:-not identifiable (driver naming)} · ${nvec} RX vector(s) · irqbalance $( ((ST_F_IRQBALANCE)) && printf 'on' || printf 'off')"
  if ((nvec > 1 && ST_F_CPUS > 1)) && [[ $irq =~ ^[0-9]+$ ]]; then
    ui_step_note warn "all ${nvec} receive interrupts run on CPU ${irq} — Quick Optimize spreads them one per CPU (irq_affinity)."
  fi
  ui_kv "RFS table" "$(sysctl_get net.core.rps_sock_flow_entries)"
  if has_cmd tc; then
    local out
    out="$(tc -s qdisc show dev "$iface" 2>/dev/null)" || out=''
    ui_kv "Root qdisc" "$(net_root_qdisc "$iface")"
    ui_kv "Qdisc drops" "$(awk '/dropped/ {gsub(/,/, "", $7); print $7 + 0; exit}' <<<"$out")"
  fi
}

_diag_conntrack_section() {
  ui_section "Conntrack"
  local count max drop early ins
  count="$(sysctl_get net.netfilter.nf_conntrack_count)"
  max="$(sysctl_get net.netfilter.nf_conntrack_max)"
  if [[ ! $count =~ ^[0-9]+$ || ! $max =~ ^[0-9]+$ || $max -eq 0 ]]; then
    ui_step_note idle "conntrack not loaded."
    return 0
  fi
  ui_kv "Entries" "${count} / ${max} ($((count * 100 / max))%)"
  IFS=' ' read -r drop early ins <<<"$(_diag_conntrack_stats)"
  ui_kv "Drops (boot)" "drop ${drop:-0} · early_drop ${early:-0} · insert_failed ${ins:-0}"
  if ((count * 100 / max >= 80)); then
    ui_step_note err "table is $((count * 100 / max))% full — new flows will be dropped; raise the tier or --users."
  fi
  if ((${early:-0} > 0 || ${drop:-0} > 0)); then
    ui_step_note warn "conntrack has dropped flows since boot (table pressure at some point)."
  fi
  return 0
}

# diagnose_network — the whole report. Read-only.
diagnose_network() {
  _plan_prerequisites
  facts_collect
  roles_resolve
  capacity_resolve
  local saved_dry=$ST_DRY_RUN
  ST_DRY_RUN=1 # policy must not load modules from a read-only report
  policy_resolve
  ST_DRY_RUN=$saved_dry

  ui_title "Diagnose — network data path"
  ui_kv "Roles" "$(roles_summary) (${ST_ROLES_SOURCE}) · engines: $(engines_summary)"
  ui_kv "Virtualization" "$ST_F_VIRT"
  _diag_cpu_section
  _diag_nic_section
  _diag_conntrack_section
  if ((ST_F_DOCKER)); then
    ui_section "Docker"
    if docker_verify; then
      ui_step_note ok "Container logs are bounded."
    else
      ui_step_note warn "json-file container logs are unbounded — Quick Optimize or Node & Docker → 3."
    fi
  fi
  ui_section "Tunnels"
  tunnel_audit
  printf '\n'
  ui_hint "No tuning was changed. Run this before and after a change, at similar traffic, to compare."
  return 0
}

# ------------------------- src/features/sysinfo.sh -------------------------
# ============================================================================
# features/sysinfo.sh — the System Status report (menu option and --status).
#
# Everything is read live from /proc, /sys and the tools that are present;
# nothing is cached from a previous run, so the report always reflects the
# machine as it is right now. Missing tools degrade to "n/a", never an error.
# ============================================================================

_meminfo_kb() { # _meminfo_kb FIELD — e.g. MemTotal
  awk -v field="$1:" '$1 == field {print $2; exit}' /proc/meminfo 2>/dev/null || printf '0'
}

# _hr_mb MB — human readable size, one decimal from a gigabyte upwards.
_hr_mb() {
  local mb="${1:-0}"
  if ((mb >= 1024)); then
    awk -v m="$mb" 'BEGIN {printf "%.1f GB", m / 1024}'
  else
    printf '%s MB' "$mb"
  fi
}

# _pct USED TOTAL — integer percentage, "0" when total is zero.
_pct() {
  if (($2 > 0)); then
    printf '%d' $(($1 * 100 / $2))
  else
    printf '0'
  fi
}

_status_system() {
  ui_section "System"
  ui_kv "Hostname" "$(hostname 2>/dev/null || cat /proc/sys/kernel/hostname 2>/dev/null || printf 'unknown')"
  ui_kv "OS" "$(os_pretty_name)"
  ui_kv "Kernel" "$(kernel_release) ($(uname -m 2>/dev/null || printf 'unknown'))"
  ui_kv "Virtualization" "$(detect_virt)"
  ui_kv "Uptime" "$(uptime_pretty)"

  local tz='n/a' ntp=''
  if has_cmd timedatectl; then
    tz="$(timedatectl show -p Timezone --value 2>/dev/null)" || tz='n/a'
    ntp="$(timedatectl show -p NTPSynchronized --value 2>/dev/null)" || ntp=''
  fi
  case "$ntp" in
    yes) ui_kv "Time" "${tz} (NTP synchronized)" ;;
    no) ui_kv "Time" "${tz} (NTP NOT synchronized)" ;;
    *) ui_kv "Time" "$tz" ;;
  esac
}

_status_cpu() {
  ui_section "CPU"
  ui_kv "Model" "$(cpu_model)"
  ui_kv "Cores" "$(cpu_cores)"
  ui_kv "Load (1/5/15m)" "$(load_avg)"
}

# _swap_backend — how swap is provided: zram, file, partition, or none.
_swap_backend() {
  [[ -r /proc/swaps ]] || {
    printf 'unknown'
    return 0
  }
  awk 'NR > 1 {
    if ($1 ~ /zram/) kind = "zram (compressed RAM)"
    else if ($2 == "file") kind = "file " $1
    else kind = $2 " " $1
    print kind
    exit
  }' /proc/swaps
}

_status_memory() {
  ui_section "Memory & Storage"
  local total_kb avail_kb swap_total_kb swap_free_kb used_mb
  total_kb="$(_meminfo_kb MemTotal)"
  avail_kb="$(_meminfo_kb MemAvailable)"
  swap_total_kb="$(_meminfo_kb SwapTotal)"
  swap_free_kb="$(_meminfo_kb SwapFree)"
  used_mb=$(((total_kb - avail_kb) / 1024))

  ui_kv "RAM" "$(_hr_mb $((total_kb / 1024))) total · $(_hr_mb "$used_mb") used · $(_hr_mb $((avail_kb / 1024))) available"
  if ((swap_total_kb > 0)); then
    ui_kv "Swap" "$(_hr_mb $(((swap_total_kb - swap_free_kb) / 1024))) used / $(_hr_mb $((swap_total_kb / 1024))) · $(_swap_backend)"
  else
    ui_kv "Swap" "disabled"
  fi
  if has_cmd df; then
    ui_kv "Disk (/)" "$(df -h / 2>/dev/null | awk 'NR == 2 {printf "%s used / %s (%s full)", $3, $2, $5}')"
  fi
}

_status_network() {
  ui_section "Network"
  local iface mtu qdisc tc_out
  iface="$(net_default_iface)" || iface=''
  ui_kv "Default IF" "${iface:-unknown}"
  if [[ -n $iface ]]; then
    mtu="$(cat "/sys/class/net/${iface}/mtu" 2>/dev/null)" || mtu='?'
    tc_out="$(tc qdisc show dev "$iface" 2>/dev/null)" || tc_out=''
    qdisc="$(awk 'NR == 1 {print $2}' <<<"$tc_out")"
    ui_kv "MTU / qdisc" "${mtu} / ${qdisc:-unknown}"
    ui_kv "Queues" "$(net_iface_queues "$iface" rx) RX · $(net_iface_queues "$iface" tx) TX · driver $(net_iface_driver "$iface")"
  fi
  local tunnels
  tunnels="$(tunnel_rows | awk -F'|' 'NF {printf "%s%s(%s) mtu %s", sep, $1, $2, $3; sep = " · "}')"
  [[ -n $tunnels ]] && ui_kv "Tunnels" "$tunnels"
  ui_kv "Gateway" "$(net_default_gw || printf 'unknown')"
  ui_kv "Public IPv4" "$(net_public_ip4)"
  ui_kv "Public IPv6" "$(net_public_ip6)"

  # Socket counts come from /proc — far cheaper than parsing `ss` output.
  if [[ -r /proc/net/sockstat ]]; then
    ui_kv "TCP sockets" "$(awk '/^TCP:/ {printf "%s in use · %s time-wait · %s orphan", $3, $7, $5}' /proc/net/sockstat)"
  fi
}

_status_dns() {
  ui_section "DNS"
  local stack
  stack="$(dns_stack)"
  case "$stack" in
    resolved) ui_kv "Resolver" "systemd-resolved" ;;
    resolvconf) ui_kv "Resolver" "resolvconf" ;;
    *) ui_kv "Resolver" "plain /etc/resolv.conf" ;;
  esac
  ui_kv "Servers in effect" "$(dns_effective_servers)"
  [[ $stack == resolved ]] && ui_kv "DNS over TLS" "$(dns_over_tls_state)"
  if [[ -L /etc/resolv.conf ]]; then
    ui_kv "resolv.conf" "symlink -> $(readlink /etc/resolv.conf 2>/dev/null)"
  else
    ui_kv "resolv.conf" "regular file"
  fi
}

_status_tuning() {
  ui_section "Kernel tuning"
  local cc
  cc="$(sysctl_get net.ipv4.tcp_congestion_control)"
  if [[ $cc == bbr* ]]; then
    ui_kv "Congestion" "${cc} (BBR active)"
  else
    ui_kv "Congestion" "${cc}"
  fi
  ui_kv "Default qdisc" "$(sysctl_get net.core.default_qdisc)"
  ui_kv "MTU probing" "$(sysctl_get net.ipv4.tcp_mtu_probing)"
  ui_kv "Forwarding" "IPv4=$(sysctl_get net.ipv4.ip_forward) · IPv6=$(sysctl_get net.ipv6.conf.all.forwarding)"
  ui_kv "Accept queues" "somaxconn=$(sysctl_get net.core.somaxconn) · backlog=$(sysctl_get net.core.netdev_max_backlog)"
  ui_kv "Socket buffers" "rmem_max=$(sysctl_get net.core.rmem_max) · wmem_max=$(sysctl_get net.core.wmem_max)"

  local ct_count ct_max
  ct_count="$(sysctl_get net.netfilter.nf_conntrack_count)"
  ct_max="$(sysctl_get net.netfilter.nf_conntrack_max)"
  if [[ $ct_count =~ ^[0-9]+$ && $ct_max =~ ^[0-9]+$ ]]; then
    ui_kv "Conntrack" "${ct_count} / ${ct_max} ($(_pct "$ct_count" "$ct_max")% used)"
  else
    ui_kv "Conntrack" "module not loaded"
  fi
}

_status_limits() {
  ui_section "Limits"
  ui_kv "nofile (this shell)" "soft=$(ulimit -Sn 2>/dev/null || printf '?') · hard=$(ulimit -Hn 2>/dev/null || printf '?')"
  if has_cmd systemctl; then
    ui_kv "systemd default" "$(systemctl show -p DefaultLimitNOFILE --value 2>/dev/null || printf 'n/a')"
  fi
  ui_kv "fs.file-max" "$(sysctl_get fs.file-max)"
  [[ -r /proc/sys/fs/file-nr ]] &&
    ui_kv "Open files" "$(awk '{print $1}' /proc/sys/fs/file-nr)"
  if has_cmd docker; then
    if grep -q 'default-ulimits' /etc/docker/daemon.json 2>/dev/null; then
      ui_kv "Docker ulimits" "configured in daemon.json"
    else
      ui_kv "Docker ulimits" "engine default (containers ignore limits.d)"
    fi
  fi
}

_status_security() {
  ui_section "Security"
  if has_cmd ufw; then
    local ufw_out=''
    ufw_out="$(ufw status 2>/dev/null)" || ufw_out=''
    ui_kv "Firewall (UFW)" "$(awk 'NR == 1 {print $2; exit}' <<<"$ufw_out" || printf 'unknown')"
  else
    ui_kv "Firewall (UFW)" "not installed"
  fi
  if has_cmd systemctl; then
    if systemctl is-active --quiet fail2ban 2>/dev/null; then
      ui_kv "fail2ban" "active"
    else
      ui_kv "fail2ban" "inactive"
    fi
    if systemctl is-enabled --quiet server-tools-mss.service 2>/dev/null; then
      ui_kv "MSS clamping" "enabled at boot"
    fi
  fi
  if has_cmd sshd; then
    local sshd_cfg port pw
    sshd_cfg="$(sshd -T 2>/dev/null)" || sshd_cfg=''
    if [[ -n $sshd_cfg ]]; then
      port="$(awk '/^port / {print $2; exit}' <<<"$sshd_cfg")"
      pw="$(awk '/^passwordauthentication / {print $2; exit}' <<<"$sshd_cfg")"
      ui_kv "SSH" "port ${port:-?} · password auth ${pw:-?}"
    fi
  fi
}

_status_servertools() {
  ui_section "Workload & ServerTools"
  ui_kv "Roles detected" "${ST_DETECTED_ROLES} · engines: $(engines_summary)"
  ui_kv "Version" "$ST_VERSION"
  local users applied
  users="$(config_get expected_users)"
  applied="$(config_get last_roles 'not applied yet') · tier $(config_get last_tier '-')"
  [[ $users =~ ^[1-9][0-9]*$ ]] && applied+=" · ${users} users"
  ui_kv "Applied" "$applied"
  ui_kv "Recorded changes" "$(manifest_entry_count) (open run: $(manifest_latest_run | grep . || printf 'none'))"
  ui_kv "Log file" "$ST_LOG_FILE"
  ui_kv "Backups" "$ST_BACKUP_DIR"
}

show_status() {
  roles_detect
  ui_logo
  ui_title "System Status"

  _status_system
  _status_cpu
  _status_memory
  _status_network
  _status_dns
  _status_tuning
  _status_limits
  _status_security
  _status_servertools

  printf '\n'
  ui_hint "\"st --dry-run\" shows which kernel keys still differ · \"st --report\" saves this to a file."
  ui_pause
}

# ------------------------- src/features/doctor.sh -------------------------
# ============================================================================
# features/doctor.sh — health check and drift detection (`--verify`).
#
# The verify contract every module follows:
#   0  applied and in effect
#   2  not configured by ServerTools (nothing to check)
#   3  configured but the live system disagrees — drift
#
# A kernel upgrade, a panel installer or a hand edit can undo tuning without
# telling anyone; this is where that becomes visible.
# ============================================================================

# Registry: "label|verify function|repair hint"
readonly -a ST_DOCTOR_CHECKS=(
  'Kernel tuning (sysctl)|sysctl_verify|re-run Quick Optimize'
  'Live qdisc on uplink|qdisc_verify|re-run Quick Optimize'
  'CPU/NIC data path|nic_verify|re-run Quick Optimize'
  'MSS clamping|mss_verify|Quick Optimize, or Network tools → 5'
  'Conntrack NOTRACK|notrack_verify|Network tools → n (re-applying also upgrades rules from older versions)'
  'Forwarding fast path|flowtable_verify|Network tools → f'
  'DNS servers|dns_verify|Quick Optimize, then pick the provider again'
  'File limits (nofile)|limits_verify|re-run Quick Optimize'
  'Docker log rotation|docker_verify|Quick Optimize, or Node & Docker → 3'
  'Swap|swap_verify|Custom Optimize, enable the swap step'
  'SSH hardening|ssh_verify|Security menu → 3'
  'IPv6 disabled|ipv6_verify|menu i, or: st --ipv6 off'
)

ST_DOCTOR_DRIFT=0
ST_DOCTOR_OK=0
ST_DOCTOR_NA=0

# _doctor_run_check LABEL FN HINT — one row of the report.
_doctor_run_check() {
  local label="$1" fn="$2" hint="$3" rc=0
  declare -F "$fn" >/dev/null 2>&1 || return 0
  "$fn" || rc=$?
  case "$rc" in
    0)
      ST_DOCTOR_OK=$((ST_DOCTOR_OK + 1))
      printf '  %s%-24s%s %sOK%s\n' "$C_KEY" "$label" "$C_RESET" "$C_OK" "$C_RESET"
      ;;
    2)
      ST_DOCTOR_NA=$((ST_DOCTOR_NA + 1))
      printf '  %s%-24s%s %snot configured%s\n' "$C_KEY" "$label" "$C_RESET" "$C_MUTED" "$C_RESET"
      ;;
    *)
      ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1))
      printf '  %s%-24s%s %sDRIFT%s — %s\n' "$C_KEY" "$label" "$C_RESET" "$C_WARN" "$C_RESET" "$hint"
      ;;
  esac
}

# _doctor_json — machine-readable result for fleet automation.
_doctor_json() {
  local entry label fn hint rc first=1
  printf '{"version":"%s","host":"%s","checks":[' \
    "$ST_VERSION" "$(hostname 2>/dev/null || printf 'unknown')"
  for entry in "${ST_DOCTOR_CHECKS[@]}"; do
    IFS='|' read -r label fn hint <<<"$entry"
    declare -F "$fn" >/dev/null 2>&1 || continue
    rc=0
    "$fn" || rc=$?
    ((first)) || printf ','
    first=0
    case "$rc" in
      0) printf '{"check":"%s","status":"ok"}' "$label" ;;
      2) printf '{"check":"%s","status":"not_configured"}' "$label" ;;
      *) printf '{"check":"%s","status":"drift","hint":"%s"}' "$label" "$hint" ;;
    esac
    case "$rc" in
      0 | 2) : ;;
      *) ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1)) ;;
    esac
  done
  printf '],"drift":%d,"roles":"%s","tier":"%s"}\n' \
    "$ST_DOCTOR_DRIFT" "$(config_get last_roles none)" "$(config_get last_tier -)"
}

# doctor_run — the whole report. Returns 0 when healthy, 3 on drift.
doctor_run() {
  ST_DOCTOR_DRIFT=0
  ST_DOCTOR_OK=0
  ST_DOCTOR_NA=0

  if ((ST_OPT_JSON)); then
    _doctor_json
    ((ST_DOCTOR_DRIFT > 0)) && return 3
    return 0
  fi

  ui_logo
  ui_title "Doctor — is everything still in effect?"
  ui_section "Checks"
  local entry label fn hint
  for entry in "${ST_DOCTOR_CHECKS[@]}"; do
    IFS='|' read -r label fn hint <<<"$entry"
    _doctor_run_check "$label" "$fn" "$hint"
  done
  ui_hr

  # Listening ports that appeared after the last apply are a silent hazard:
  # an outgoing connection can steal a port a node still needs.
  local unreserved
  unreserved="$(_doctor_unreserved_ports)"
  if [[ -n $unreserved ]]; then
    ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1))
    printf '  %s%-24s%s %sDRIFT%s — %s not reserved; re-run Quick Optimize\n' \
      "$C_KEY" "Reserved service ports" "$C_RESET" "$C_WARN" "$C_RESET" "$unreserved"
    ui_hr
  fi

  ui_section "Effect since the last baseline"
  snapshot_report || printf '  (no baseline yet — it is taken on the next optimize run)\n'
  ui_hr

  if ((ST_DOCTOR_DRIFT > 0)); then
    printf '%s%d check(s) drifted%s · %d OK · %d not configured\n' \
      "$C_WARN" "$ST_DOCTOR_DRIFT" "$C_RESET" "$ST_DOCTOR_OK" "$ST_DOCTOR_NA"
    printf 'Run "st --dry-run" to see exactly which kernel keys differ.\n'
    return 3
  fi
  printf '%sEverything ServerTools configured is still in effect.%s (%d OK, %d not configured)\n' \
    "$C_OK" "$C_RESET" "$ST_DOCTOR_OK" "$ST_DOCTOR_NA"
  return 0
}

# _doctor_unreserved_ports — listening ports inside the ephemeral range that
# the current sysctl file does not reserve (typically inbounds added later).
_doctor_unreserved_ports() {
  local file
  file="$(sysctl_file_in_use)"
  [[ -f $file ]] || return 0
  local reserved port missing=''
  reserved="$(awk -F'= *' '/ip_local_reserved_ports/ {print $2; exit}' "$file")" || reserved=''
  [[ -n $reserved ]] || return 0

  # Same source as the apply step, so a service that started later shows up
  # while transient proxy sockets do not raise a false alarm.
  while IFS= read -r port; do
    [[ $port =~ ^[0-9]+$ ]] || continue
    port_in_list "$port" "$reserved" || missing+="${port} "
  done < <(listening_service_ports)

  printf '%s' "${missing% }"
}

# ------------------------- src/state/migrate.sh -------------------------
# ============================================================================
# state/migrate.sh — one-time upgrade of a host tuned by ServerTools pre-2.4.5.
#
# pre-2.4.5 state stays valid for rollback (the manifest format is a superset), but
# pre-2.4.5 left four things live on servers that 2.4.5 now knows to be wrong. They are
# fixed here, once, as tracked changes of the current run — so a rollback of
# this run reverts the migration too:
#   1. the MSS unit had no ExecStop and re-appended a duplicate rule on every
#      restart;
#   2. NOTRACK rules matched forwarded traffic too (breaks NAT/VPN clients
#      on the proxy port);
#   3. `tc qdisc replace root fq` collapsed a multi-queue NIC's mq into one
#      root qdisc (one lock for every CPU);
#   4. the CPU/NIC boot script mapped every CPU to every TX queue and ran RPS
#      regardless of role — re-planned on the next optimize run.
# Never runs under --dry-run, --status or --rollback.
# ============================================================================

ST_MIGRATE_NOTES=()

# migrate_pending — 0 when this host carries pre-2.4.5 state not yet migrated.
migrate_pending() {
  [[ "$(config_get schema '')" == "$ST_SCHEMA" ]] && return 1
  [[ -f $ST_MANIFEST_FILE ]] && (($(manifest_entry_count) > 0))
}

_migrate_mss_unit() {
  [[ -f $ST_MSS_UNIT ]] || return 0
  grep -q '^ExecStop=' "$ST_MSS_UNIT" && return 0
  fw_has_iptables || return 0
  # Collapse the duplicates pre-2.4.5 unit appended into exactly one live rule.
  fw_rule_remove iptables mangle FORWARD "${ST_MSS_RULE[@]}" || log_warn "Could not de-duplicate the IPv4 MSS rule."
  fw_rule_ensure iptables mangle FORWARD "${ST_MSS_RULE[@]}" || log_warn "Could not re-add the IPv4 MSS rule."
  if has_cmd ip6tables; then
    fw_rule_remove ip6tables mangle FORWARD "${ST_MSS_RULE[@]}" || log_debug "no IPv6 MSS duplicates"
    fw_rule_ensure ip6tables mangle FORWARD "${ST_MSS_RULE[@]}" || log_debug "no IPv6 netfilter"
  fi
  st_track_file "$ST_MSS_UNIT"
  _mss_unit_iptables >"$ST_MSS_UNIT"
  ST_MIGRATE_NOTES+=("MSS unit: idempotent start + ExecStop (no duplicate rules; rollback removes it live)")
}

_migrate_notrack() {
  local rc=0
  notrack_migrate_v2 || rc=$?
  case "$rc" in
    0) ST_MIGRATE_NOTES+=("NOTRACK rules now match only traffic addressed to this host (NAT/VPN clients on the same port work again)") ;;
    1) log_warn "Could not migrate the NOTRACK rules of the older version — re-apply them from Network tools → n." ;;
  esac
  return 0
}

_migrate_qdisc() {
  local kind handle txq
  [[ -n $ST_F_IFACE ]] || return 0
  txq="$(net_iface_queues "$ST_F_IFACE" tx)"
  ((txq > 1)) || return 0
  IFS=' ' read -r kind handle <<<"$(net_root_qdisc "$ST_F_IFACE")"
  [[ $kind == fq || $kind == fq_codel ]] || return 0
  [[ $handle != 0: ]] || return 0
  st_track_qdisc "$ST_F_IFACE"
  if qdisc_reattach_default "$ST_F_IFACE"; then
    ST_MIGRATE_NOTES+=("${ST_F_IFACE}: single root ${kind} replaced by mq (${txq} TX queues no longer share one lock)")
  else
    log_warn "Could not rebuild the qdisc on ${ST_F_IFACE} — it is corrected at the next reboot."
  fi
}

_migrate_perf() {
  [[ -f $ST_PERF_BOOT ]] || return 0
  grep -q '^printf %s ' "$ST_PERF_BOOT" || return 0
  ST_MIGRATE_NOTES+=("CPU/NIC tuning is from an older version (RPS/XPS not role-aware) — the next Quick Optimize re-plans it")
}

# migrate_unit_order — rule units written by earlier versions started BEFORE
# the firewall managers, which then flushed their rules at boot. Re-order
# them in place (tracked); runs before every optimize, a no-op once fixed.
migrate_unit_order() {
  ((ST_DRY_RUN)) && return 0
  local unit fixed=0
  for unit in "$ST_MSS_UNIT" "$ST_NOTRACK_UNIT" "$ST_FT_UNIT"; do
    [[ -f $unit ]] || continue
    grep -q '^After=.*firewalld\.service' "$unit" && continue
    st_track_file "$unit"
    sed -i "s|^After=\(.*\)$|After=\1 ${ST_FW_AFTER}|" "$unit"
    fixed=$((fixed + 1))
  done
  ((fixed)) || return 0
  has_cmd systemctl && { systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."; }
  log_info "${fixed} firewall rule unit(s) now start after the firewall managers (rules survive reboots)."
  return 0
}

# migrate_run — perform the migration once; prints what changed.
migrate_run() {
  ((ST_DRY_RUN)) && return 0
  migrate_unit_order
  if ! migrate_pending; then
    [[ "$(config_get schema '')" == "$ST_SCHEMA" ]] || config_set schema "$ST_SCHEMA"
    return 0
  fi
  facts_collect
  ST_MIGRATE_NOTES=()
  log_info "Migrating ServerTools 2.4.4-or-older state to schema ${ST_SCHEMA}."
  _migrate_mss_unit
  _migrate_notrack
  _migrate_qdisc
  _migrate_perf
  has_cmd systemctl && { systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."; }

  local last
  last="$(config_get last_profile '')"
  if [[ -n $last && -z $(config_get last_roles '') ]]; then
    config_set last_roles "$(roles_from_profile "$last" | tr ' ' ',' || printf '%s' "$last")"
  fi
  config_set schema "$ST_SCHEMA"

  if ((${#ST_MIGRATE_NOTES[@]})); then
    printf '%sUpgraded this host from ServerTools 2.4.4 or older:%s\n' "$C_TITLE" "$C_RESET"
    local n
    for n in "${ST_MIGRATE_NOTES[@]}"; do
      printf '  %s %s\n' "$(ui_badge ok)" "$n"
      log_info "migrate: ${n}"
    done
    printf '\n'
  fi
  return 0
}

# ------------------------- src/ui/flows.sh -------------------------
# ============================================================================
# ui/flows.sh — Quick / Custom / Auto / Dry-run optimize flows:
#   resolve (roles → capacity → policy) → show the plan WITH reasons →
#   confirm → apply steps with honest per-step outcomes → summary.
# ============================================================================

# CLI inputs, filled by 99-main.sh.
ST_CLI_ROLES=''
ST_AUTO_DNS=''
ST_AUTO_SWAP=1
ST_AUTO_LIMITS=1
ST_AUTO_EXTRAS=1
ST_AUTO_PERF=1
ST_AUTO_MSS=1
ST_AUTO_DOCKER=1

# The optimize steps, in run order: "id|function|title". Swap runs BEFORE
# sysctl on purpose (vm.swappiness depends on the backend), channels before
# steering. A new tuner is one line here (+ a Doctor row, + build.sh).
readonly -a ST_OPTIMIZE_STEPS=(
  'swap|swap_apply|Swap'
  'sysctl|sysctl_apply|Kernel network tuning (sysctl)'
  'qdisc|qdisc_apply|Queueing discipline'
  'perf|nic_apply|CPU & NIC data path (channels, offloads, IRQs, RPS/XPS)'
  'mss|mss_apply|MSS clamping for forwarded TCP'
  'limits|limits_apply|File-descriptor limits (nofile)'
  'extras|extras_apply|Journald cap & NTP'
  'docker|docker_apply|Docker engine (log rotation, live-restore, nofile)'
  'dns|dns_apply|DNS'
)

# _optimize_title ID TITLE — the step title with this run's specifics.
_optimize_title() {
  case "$1" in
    sysctl) printf '%s, tier %s' "$2" "$ST_TIER" ;;
    qdisc) printf '%s on %s (%s)' "$2" "${ST_F_IFACE:-uplink}" "$ST_QDISC" ;;
    dns) printf '%s (%s / %s)' "$2" "$ST_DNS1" "$ST_DNS2" ;;
    *) printf '%s' "$2" ;;
  esac
}

# _optimize_applicable ID — steps the policy rules out are not even listed.
_optimize_applicable() {
  case "$1" in
    mss) ((ST_P_MSS)) ;;
    docker) ((ST_P_DOCKER)) ;;
    *) return 0 ;;
  esac
}

# plan_resolve [ROLES] — the full decision chain, shared by every flow.
# Prerequisites are installed first (quietly; reported in the plan) so the
# facts the policy reads — channels, offloads, nft support — are complete.
# shellcheck disable=SC2120 # the argument is optional
plan_resolve() {
  _plan_prerequisites
  roles_resolve "${1:-$ST_CLI_ROLES}"
  capacity_resolve
  policy_resolve
}

_plan_prerequisites() {
  local missing
  missing="$(deps_missing core | cut -f1 | paste -sd' ' -)"
  [[ -n $missing ]] || return 0
  if ((ST_DRY_RUN)); then
    printf '%sPrerequisites a real run would install:%s %s\n' "$C_MUTED" "$C_RESET" "$missing"
    return 0
  fi
  printf '%sInstalling prerequisites:%s %s …\n' "$C_MUTED" "$C_RESET" "$missing"
  deps_ensure core || log_debug "prerequisites incomplete (fallbacks in use)"
  facts_collect force
  return 0
}

# _plan_cpu_hints — opt-in features that cut CPU on this kind of host and
# are not enabled yet. They change the firewall path, so they stay a choice
# (Network & VPN Tools) instead of a Quick Optimize step.
_plan_cpu_hints() {
  local -a hints=()
  local rc
  if role_has relay; then
    rc=0
    flowtable_verify || rc=$?
    ((rc == 2)) && hints+=("nftables fast path (menu 7 → f): forwarded NAT flows skip most of netfilter — the largest CPU saving on a relay")
  fi
  if role_has proxy; then
    rc=0
    notrack_verify || rc=$?
    ((rc == 2)) && hints+=("NOTRACK for proxy ports (menu 7 → n): no conntrack work for connections to the proxy itself")
  fi
  ((${#hints[@]})) || return 0
  ui_section "Lower CPU further (opt-in)"
  local h
  for h in "${hints[@]}"; do
    ui_step_note idle "$h"
  done
  return 0
}

plan_show() {
  ui_section "What this server does"
  ui_kv "Roles" "$(roles_summary) (${ST_ROLES_SOURCE})"
  ui_kv "Engines" "$(engines_summary)"
  ui_kv "Uplink" "${ST_F_IFACE:-?} · ${ST_F_RXQ} RX / ${ST_F_TXQ} TX queues · ${ST_F_CPUS} CPUs · ${ST_F_VIRT}"

  ui_section "Capacity"
  if ((ST_EXPECTED_USERS > 0)); then
    ui_kv "Sizing" "${ST_EXPECTED_USERS} expected users (conntrack from users, buffers from RAM tier ${ST_TIER})"
  else
    ui_kv "Tier" "${ST_TIER} — up to ${ST_TIER_USERS} concurrent users"
  fi
  ui_kv "Socket buffers" "up to ${ST_BUF_MB} MB per socket"
  ((ST_P_CONNTRACK)) && ui_kv "Conntrack" "${ST_CONNTRACK} entries (~$(capacity_conntrack_ram_mb) MB kernel RAM worst case)"
  local warn
  warn="$(capacity_warning)"
  if [[ -n $warn ]]; then
    printf '    %sCapacity warning:%s %s\n' "$C_WARN" "$C_RESET" "$warn"
    log_info "capacity warning: ${warn}"
  fi

  ui_section "Decisions (and why)"
  policy_print
  _plan_cpu_hints
  if ((${#ST_F_TUNNELS[@]})); then
    ui_section "Tunnels"
    tunnel_audit
  fi
  return 0
}

# _optimize_run STEP_ID... — run the listed steps in table order, skipping
# those the policy rules out, then summarise and offer follow-ups.
_optimize_run() {
  local wanted entry id fn title
  wanted=" $(join_sp "$@") "
  local -a run=()
  for entry in "${ST_OPTIMIZE_STEPS[@]}"; do
    IFS='|' read -r id fn title <<<"$entry"
    [[ $wanted == *" ${id} "* ]] && _optimize_applicable "$id" && run+=("$entry")
  done
  ST_STEP_RESULTS=()
  ST_STEP_IDX=0
  ST_STEP_TOTAL=${#run[@]}
  # Baseline first: counters must be read before anything is changed.
  snapshot_save
  ui_hr
  for entry in "${run[@]}"; do
    IFS='|' read -r id fn title <<<"$entry"
    st_run_step "$(_optimize_title "$id" "$title")" "$fn"
  done
  st_report_summary
  [[ $wanted == *' dns '* ]] && ui_kv "DNS in effect" "$(dns_effective_servers)"
  docker_offer_restart
  _offer_service_restart
  config_set last_roles "${ST_ROLES// /,}"
  config_set last_tier "$ST_TIER"
  config_unset last_profile
  backup_prune 10
  return 0
}

# _optimize_run_list "ID ID ..." — space-separated form (the global IFS has
# no space, so an unquoted list would not split).
_optimize_run_list() {
  local -a ids=()
  IFS=' ' read -ra ids <<<"$1"
  _optimize_run "${ids[@]}"
}

# _restart_candidates — "kind<TAB>name" for running workloads that keep their
# old nofile until restarted, found with the engine signatures (one source
# of truth with role detection). Containers only count when daemon.json
# gives them a limit: otherwise they inherit dockerd's, and restarting the
# container alone changes nothing.
_restart_candidates() {
  local entry role _label src re line unit
  local -A seen=()
  for entry in "${ST_ENGINE_SIGNATURES[@]}"; do
    IFS=';' read -r role _label src re <<<"$entry"
    # Socket-heavy userspace engines only: a kernel WireGuard unit holds no
    # descriptors, and restarting it would only drop the tunnel.
    [[ $role == proxy || $role == utunnel ]] || continue
    case "$src" in
      c)
        grep -q 'default-ulimits' "$ST_DOCKER_DAEMON" 2>/dev/null || continue
        while IFS= read -r line; do
          [[ -n $line && -z ${seen[c${line%% *}]:-} ]] || continue
          seen[c${line%% *}]=1
          printf 'container\t%s\n' "${line%% *}"
        done < <(grep -iE "$re" <<<"$ST_F_CONTAINERS")
        ;;
      p | u)
        while IFS= read -r unit; do
          [[ -n $unit && -z ${seen[u$unit]:-} ]] || continue
          seen[u$unit]=1
          printf 'service\t%s\n' "$unit"
        done < <(grep -iE "^(${re})(-server|-client|@.+)?$" <<<"$ST_F_UNITS")
        ;;
    esac
  done
  return 0
}

# _offer_service_restart — running services keep their old nofile limit until
# restarted; offer to restart detected workloads (interactive), or say so.
_offer_service_restart() {
  ((ST_LIMITS_CHANGED)) || return 0
  local list
  list="$(_restart_candidates)"
  if ((ST_F_DOCKER)) && ! grep -q 'default-ulimits' "$ST_DOCKER_DAEMON" 2>/dev/null; then
    printf '%sNote:%s containers take their file limit from dockerd, not limits.d —\n' "$C_MUTED" "$C_RESET"
    printf 'the Docker engine step (or Node & Docker → 3) sets it for them.\n'
  fi
  [[ -n $list ]] || return 0

  if ((ST_OPT_BATCH)); then
    printf '%sNote:%s restart these so they pick up the new limits: %s\n' \
      "$C_WARN" "$C_RESET" "$(cut -f2 <<<"$list" | paste -sd' ' -)"
    return 0
  fi

  printf '%sA restart briefly disconnects the users served by that service.%s\n' "$C_WARN" "$C_RESET"
  # FD 3: with the list on stdin, ui_confirm's read would consume it.
  local kind name ok
  while IFS=$'\t' read -r kind name <&3; do
    [[ -n $name ]] || continue
    ui_confirm "Restart ${kind} '${name}' now?" || continue
    ok=0
    if [[ $kind == container ]]; then
      run_bounded 60 docker restart "$name" >/dev/null 2>>"$ST_LOG_FILE" && ok=1
    else
      systemctl restart "$name" 2>>"$ST_LOG_FILE" && ok=1
    fi
    if ((ok)); then
      printf '%sRestarted:%s %s\n' "$C_OK" "$C_RESET" "$name"
    else
      log_warn "Could not restart ${name}."
    fi
  done 3<<<"$list"
  return 0
}

quick_optimize() {
  ui_logo
  ui_title "Quick Optimize"
  migrate_run
  plan_resolve
  printf 'The base layer always optimizes the whole server; the detected roles\n'
  printf 'decide the specialised tuning on top of it.\n'
  plan_show
  ui_hr

  local with_dns=0
  dns_select_menu && with_dns=1
  printf '\n'
  if ! ui_confirm "Apply the plan above?"; then
    ui_pause
    return 0
  fi
  local steps='swap sysctl qdisc perf mss limits extras docker'
  ((with_dns)) && steps+=' dns'
  _optimize_run_list "$steps"
  ui_pause
}

# auto_optimize — the non-interactive flow behind --auto. DNS is only touched
# when --dns was given.
auto_optimize() {
  migrate_run
  plan_resolve
  local with_dns=0
  if [[ -n $ST_AUTO_DNS ]]; then
    dns_resolve_cli "$ST_AUTO_DNS" || die "Invalid --dns '${ST_AUTO_DNS}' (provider name or ip1,ip2)."
    with_dns=1
  fi
  ui_title "Auto Optimize (non-interactive)"
  plan_show
  local steps='sysctl qdisc'
  ((ST_AUTO_SWAP)) && steps+=' swap'
  ((ST_AUTO_PERF)) && steps+=' perf'
  ((ST_AUTO_MSS)) && steps+=' mss'
  ((ST_AUTO_LIMITS)) && steps+=' limits'
  ((ST_AUTO_EXTRAS)) && steps+=' extras'
  ((ST_AUTO_DOCKER)) && steps+=' docker'
  ((with_dns)) && steps+=' dns'
  _optimize_run_list "$steps"
}

# dry_run_optimize — --dry-run: the plan, the exact sysctl diff and the /sys
# writes. Applies absolutely nothing.
dry_run_optimize() {
  plan_resolve
  ui_title "Dry Run — nothing will be applied"
  plan_show
  ui_hr
  sysctl_dry_run
  local plan eplan
  eplan="$(nic_ethtool_plan)"
  plan="$(nic_plan)"
  printf '\n%s[CPU/NIC writes]%s\n' "$C_TITLE" "$C_RESET"
  [[ -n $eplan ]] && awk -F'\t' '{printf "  ethtool %-52s %s\n", $1 " " $2, $3}' <<<"$eplan"
  if [[ -n $plan ]]; then
    awk -F'\t' '{printf "  %-60s %s\n", $1, $2}' <<<"$plan"
  elif [[ -z $eplan ]]; then
    printf '  (none on this host)\n'
  fi
  if [[ -n $eplan ]] && grep -q channels <<<"$eplan"; then
    printf '  %s(queue paths above are the current ones; the real run re-reads them after the channel change)%s\n' "$C_MUTED" "$C_RESET"
  fi
  docker_dry_run
  printf '\nA real run would also cover: live qdisc on %s, %snofile limits,\n' \
    "${ST_F_IFACE:-the uplink}" "$( ((ST_P_MSS)) && printf 'MSS clamping, ')"
  printf 'journald cap & NTP, swap%s.\n' "$([[ -n $ST_AUTO_DNS ]] && printf ', DNS')"
  if migrate_pending; then
    printf '%sThis host carries state from ServerTools 2.4.4 or older; a real run migrates it first.%s\n' "$C_WARN" "$C_RESET"
  fi
}

# _custom_pick_roles — multi-select from the catalog; Enter keeps detection.
_custom_pick_roles() {
  local entry id title desc i=1 answer pick out=''
  local -a ids=()
  printf '%s[Roles]%s detected: %s\n' "$C_TITLE" "$C_RESET" "$(roles_summary)"
  for entry in "${ST_ROLE_CATALOG[@]}"; do
    IFS=';' read -r id title desc <<<"$entry"
    ids+=("$id")
    ui_menu_item "$i" "$title" "$desc"
    i=$((i + 1))
  done
  read -rp "Select one or more (e.g. 1,4) [Enter=detected]: " answer || answer=''
  [[ -n $answer ]] || return 0
  while IFS= read -r pick; do
    [[ $pick =~ ^[0-9]+$ ]] && ((pick >= 1 && pick <= ${#ids[@]})) && out+="${out:+,}${ids[pick - 1]}"
  done < <(ports_split "$answer")
  if [[ -n $out ]]; then
    roles_resolve "$out"
    ST_ROLES_SOURCE='manual'
    if ui_confirm "Remember these roles for future runs?"; then config_set roles "$out"; fi
  fi
  return 0
}

custom_optimize() {
  ui_logo
  ui_title "Custom Optimize"
  migrate_run
  roles_resolve
  _custom_pick_roles

  local tier_choice users_in
  capacity_resolve
  read -rp "Capacity tier — auto picked ${ST_TIER} (up to ${ST_TIER_USERS} users). Override [S/M/L/XL, Enter=keep]: " tier_choice || tier_choice=''
  case "${tier_choice^^}" in
    S | M | L | XL)
      # This run uses it either way; saving it is a separate choice.
      ST_CLI_TIER="${tier_choice^^}"
      ui_confirm "Remember tier ${ST_CLI_TIER} for future runs?" && config_set capacity_tier "$ST_CLI_TIER"
      ;;
  esac
  read -rp "Expected concurrent users [Enter=size by RAM, 0=reset saved value]: " users_in || users_in=''
  [[ $users_in =~ ^[0-9]+$ ]] && config_set expected_users "$users_in"
  capacity_resolve
  policy_resolve

  plan_show
  ui_hr
  if ! ui_confirm_yes "Apply sysctl + live qdisc tuning? (the core step)"; then
    printf 'Nothing to do without the core step.\n'
    ui_pause
    return 0
  fi
  local steps='sysctl qdisc'
  ui_confirm_yes "Tune the CPU/NIC data path (channels, offloads, IRQs, RPS/XPS as planned)?" && steps+=' perf'
  ((ST_P_MSS)) && ui_confirm_yes "Clamp MSS on forwarded TCP?" && steps+=' mss'
  ui_confirm_yes "Raise file-descriptor limits?" && steps+=' limits'
  ui_confirm_yes "Cap journald disk usage and enable NTP?" && steps+=' extras'
  ((ST_P_DOCKER)) && ui_confirm_yes "Bound Docker container logs, enable live-restore and container nofile?" && steps+=' docker'
  ui_confirm_yes "Create swap if none exists?" && steps+=' swap'
  dns_select_menu && steps+=' dns'

  printf '\n'
  if ! ui_confirm "Apply now?"; then
    ui_pause
    return 0
  fi
  _optimize_run_list "$steps"
  ui_pause
}

# ------------------------- src/ui/menu.sh -------------------------
# ============================================================================
# ui/menu.sh — interactive main menu and sub-screens.
# The dashboard must render instantly: everything network-bound is cached
# (public IP is fetched at most once per process, in lib/net.sh).
# ============================================================================

# _dash_row LABEL VALUE — one compact dashboard line.
_dash_row() {
  printf '  %s%-9s%s %s\n' "$C_KEY" "$1" "$C_RESET" "$2"
}

menu_dashboard() {
  ui_logo
  local applied status
  applied="$(config_get last_roles '')"
  if [[ -n $applied ]]; then
    status="$(ui_badge ok) optimized ${C_MUTED}· ${applied//,/, } · tier $(config_get last_tier '-')${C_RESET}"
    # Tuning that a reboot or another tool undid must not read as "optimized".
    if ! sysctl_verify >/dev/null 2>&1 && ((${#ST_SYSCTL_DRIFT[@]})); then
      status="$(ui_badge warn) ${#ST_SYSCTL_DRIFT[@]} kernel setting(s) no longer in effect ${C_MUTED}· press 4 (Doctor) or 1 to re-apply${C_RESET}"
    fi
  else
    status="$(ui_badge idle) not optimized yet ${C_MUTED}· run Quick Optimize${C_RESET}"
  fi
  _dash_row "Host" "$(hostname 2>/dev/null || printf 'unknown') · $(os_pretty_name) · $(kernel_release)"
  _dash_row "Machine" "${ST_F_CPUS} vCPU · ${ST_F_RAM_MB} MB RAM · up $(uptime_pretty)"
  _dash_row "Network" "$(net_public_ip4) · cc=$(sysctl_get net.ipv4.tcp_congestion_control) · $(sysctl_get net.core.default_qdisc) · IPv6 $(ipv6_state)"
  _dash_row "Roles" "${ST_DETECTED_ROLES// /, } · $(engines_summary)"
  _dash_row "State" "$status"
}

menu_rollback() {
  ui_logo
  ui_title "Rollback"
  local run choice
  run="$(manifest_latest_run)"
  if [[ -z $run ]]; then
    printf 'No recorded changes left to roll back.\n'
    ui_pause
    return 0
  fi
  printf 'Newest open run: %s%s%s · %s change(s) recorded in total\n' \
    "$C_ACCENT" "$run" "$C_RESET" "$(manifest_entry_count)"
  ui_hr
  ui_menu_item 1 "Undo the newest run" "files, units and live values; again = one run further back"
  ui_menu_item 2 "Restore original state" "back to before ServerTools ever ran"
  ui_menu_item 0 "Back"
  read -rp "$(_ui_prompt)" choice || return 0
  case "${choice:-}" in
    1) if ui_confirm "Revert all changes from run ${run}?"; then rollback_latest || st_escalate_exit 3; fi ;;
    2)
      printf '%sThis undoes every ServerTools change on this host.%s\n' "$C_WARN" "$C_RESET"
      if ui_confirm "Restore the original (factory) state?"; then rollback_original || st_escalate_exit 3; fi
      ;;
    *) return 0 ;;
  esac
  ui_pause
}

# _settings_edit — change one registered config key, validated.
_settings_edit() {
  local key value
  read -rp "Key to change (Enter = cancel): " key || return 0
  [[ -n $key ]] || return 0
  if ! config_known "$key"; then
    printf '%sUnknown key%s %s.\n' "$C_ERR" "$C_RESET" "$key"
    return 0
  fi
  read -rp "New value for ${key} (current: $(config_get "$key"); 'default' resets): " value || return 0
  if [[ $value == default ]]; then
    config_unset "$key"
    printf 'Reset %s to its default (%s).\n' "$key" "$(config_default "$key")"
  elif config_validate "$key" "$value"; then
    config_set "$key" "$value"
    printf '%sSaved.%s It applies on the next optimize run.\n' "$C_OK" "$C_RESET"
  else
    printf '%sInvalid value%s for %s — nothing changed.\n' "$C_ERR" "$C_RESET" "$key"
  fi
  return 0
}

menu_settings() {
  local choice
  while true; do
    ui_logo
    ui_title "Settings & Maintenance"
    ui_kv "Version" "$ST_VERSION"
    ui_kv "Config file" "$ST_CONFIG_FILE"
    ui_kv "Log file" "$ST_LOG_FILE"
    ui_kv "Backups" "$ST_BACKUP_DIR"
    ui_kv "Recorded changes" "$(manifest_entry_count)"
    ui_section "Tunables"
    config_print
    ui_hr
    ui_menu_item 1 "Change a setting" "validated; applies on the next optimize"
    ui_menu_item 2 "Install 'st' command" "run 'st' instead of the one-liner"
    ui_menu_item 3 "Check for updates" "self-update from the latest release"
    ui_menu_item 0 "Back"
    read -rp "$(_ui_prompt)" choice || return 0
    case "${choice:-}" in
      1)
        _settings_edit
        ui_pause
        ;;
      2)
        st_self_install || log_warn "Install did not complete."
        ui_pause
        ;;
      3)
        st_self_update || log_warn "Update did not complete."
        ui_pause
        ;;
      0) return 0 ;;
      *) ui_invalid ;;
    esac
  done
}

main_menu() {
  facts_collect
  roles_detect
  if migrate_pending; then
    ui_logo
    printf '%sThis host was tuned by ServerTools 2.4.4 or older.%s This version fixes a few things it left live\n' "$C_WARN" "$C_RESET"
    printf '(MSS/NOTRACK rules, a single-lock qdisc on multi-queue NICs). The changes are\n'
    printf 'tracked, so a rollback undoes them.\n'
    if ui_confirm_yes "Apply these fixes now?"; then migrate_run; fi
    ui_pause
  fi
  local choice
  while true; do
    menu_dashboard
    ui_hr
    ui_menu_group "Optimize"
    ui_menu_item 1 "Quick Optimize" "detect roles and tune safely · recommended"
    ui_menu_item 2 "Custom Optimize" "choose roles, capacity and steps"
    ui_menu_group "Inspect"
    ui_menu_item 3 "System Status" "full live report"
    ui_menu_item 4 "Doctor" "drift check — still in effect?"
    ui_menu_item d "Diagnose data path" "why is a core hot? measured, read-only"
    ui_menu_group "Manage"
    ui_menu_item 5 "Rollback" "undo changes safely"
    ui_menu_item 6 "Security" "UFW · fail2ban · SSH"
    ui_menu_item 7 "Network & VPN Tools" "MSS · NOTRACK · fast path · speed"
    ui_menu_item 8 "Node & Docker" "backups · installers · Docker engine"
    ui_menu_item i "IPv6 on / off" "now: $(ipv6_state) · stays that way after reboot"
    ui_menu_group "System"
    ui_menu_item 9 "Settings" "tunables · install · update"
    ui_menu_item 0 "Exit"
    printf '\n'
    ui_hint "New here? Press 1 — it detects what this server does and tunes it safely."
    read -rp "$(_ui_prompt)" choice || {
      printf '\n'
      return 0
    }
    case "${choice:-}" in
      1) quick_optimize ;;
      2) custom_optimize ;;
      3) show_status ;;
      4)
        doctor_run || st_escalate_exit 3 # drift is reported on screen
        ui_pause
        ;;
      d | D)
        diagnose_network || st_escalate_exit 3
        ui_pause
        ;;
      5) menu_rollback ;;
      6) security_menu ;;
      7) tools_menu ;;
      8) node_menu ;;
      i | I)
        ui_logo
        ipv6_control
        ui_pause
        ;;
      9) menu_settings ;;
      0) return 0 ;;
      *) ui_invalid ;;
    esac
  done
}

# ------------------------- src/99-main.sh -------------------------
# ============================================================================
# 99-main.sh — CLI argument parsing and the program entrypoint.
# This file MUST be last in the build order (see build.sh SOURCES).
# ============================================================================

usage() {
  cat <<EOF
${ST_NAME} v${ST_VERSION} — Linux server optimization for VPN, proxy, tunnel
and relay servers. ${ST_REPO_URL}

Usage: server-tools.sh [OPTIONS]   (installed: st [OPTIONS])

Actions (no action starts the interactive menu):
  --status              Print the full system status report and exit
  --auto                Non-interactive optimize for the detected roles
  --dry-run             Show the plan, the reasons and the exact diff; apply NOTHING
  --diagnose            Measure the network data path (per-core softirq, drops,
                        queues, conntrack, tunnels) — read-only, ~3 s
  --verify              Check whether everything applied is still in effect
  --report              Print + save a plain-text support report
  --rollback            Revert the newest open run (again = one run further back)
  --rollback-original   Restore the state from before ServerTools ever ran
  --settings            List every tunable with its current value
  --set KEY=VALUE       Save a tunable (validated; repeatable; combines with --auto)
  --install             Install as the 'st' command (/usr/local/bin/st)
  --update              Self-update from the latest GitHub release
  --ipv6 on|off|status  Switch the IPv6 stack on/off (persists across reboots)
  --speedtest           Bandwidth test (Ookla, nearest server) + result history

Options for --auto and --dry-run:
  --role LIST           Roles to tune for, comma separated (default: detected):
                        proxy, panel, vpn, tunnel, relay, utunnel, web, db, general
  --profile NAME        older profile names still work: general | vpn-node | wireguard |
                        panel | relay | full
  --tier T              Capacity tier: S | M | L | XL (default: by RAM)
  --users N             Expected concurrent users — sizes conntrack from the
                        real user count instead of RAM (with a RAM warning)
  --dns VALUE           Provider (cloudflare|google|quad9|opendns|shecan|
                        electro|begzar) or custom "primary,secondary"
  --no-swap             Skip the swap step
  --no-limits           Skip the nofile limits step
  --no-extras           Skip the journald/NTP step
  --no-perf             Skip the CPU/NIC data-path step (RPS/XPS, governor, THP)
  --no-mss              Skip MSS clamping (otherwise on for vpn/tunnel/relay roles)
  --no-docker           Skip the Docker engine step (log rotation, live-restore, nofile)
  --no-install          Never install missing prerequisites this run
                        (default: installed automatically — ethtool, nftables, …)

General options:
  --json                Machine-readable output (--verify)
  --no-color            Disable colored output (NO_COLOR env also honoured)
  --debug               Verbose logging to console and log file
  -v, --version         Print version and exit
  -h, --help            Show this help

Exit codes:
  0  everything succeeded    1  at least one step failed
  2  usage error             3  applied, but with warnings / drift found

Examples:
  st --auto --role relay,tunnel           # a GRE/DNAT relay
  st --auto --profile vpn-node --users 10000 --dns cloudflare
  st --set rps_mode=off --auto            # A/B-test software steering
  st --verify --json                      # drift check from your own automation
EOF
}

_need_value() { # _need_value OPTION VALUE
  if [[ -z ${2:-} ]]; then
    printf 'Missing value for %s\n' "$1" >&2
    exit 2
  fi
}

_usage_error() {
  printf '%s\n' "$1" >&2
  exit 2
}

ST_CLI_IPV6=''

main() {
  local action="menu" tuning_opts=''
  local -a sets=()
  while (($# > 0)); do
    case "$1" in
      -v | --version)
        printf '%s %s\n' "$ST_NAME" "$ST_VERSION"
        return 0
        ;;
      -h | --help)
        usage
        return 0
        ;;
      --status) action="status" ;;
      --rollback) action="rollback" ;;
      --rollback-original) action="rollback_original" ;;
      --auto) action="auto" ;;
      --dry-run) action="dryrun" ;;
      --diagnose) action="diagnose" ;;
      --verify | --doctor) action="verify" ;;
      --report) action="report" ;;
      --install) action="install" ;;
      --update) action="update" ;;
      --settings) action="settings" ;;
      --speedtest) action="speedtest" ;;
      --ipv6)
        _need_value "$1" "${2:-}"
        shift
        case "$1" in
          on | off | status) ST_CLI_IPV6="$1" ;;
          *) _usage_error "Invalid --ipv6 '${1}' (on, off or status)." ;;
        esac
        action="ipv6"
        ;;
      --set)
        _need_value "$1" "${2:-}"
        shift
        sets+=("$1")
        [[ $action == menu ]] && action="set"
        ;;
      --role | --roles)
        _need_value "$1" "${2:-}"
        shift
        roles_normalize "$1" >/dev/null ||
          _usage_error "Invalid --role '${1}' (proxy, panel, vpn, tunnel, relay, utunnel, web, db, general)."
        ST_CLI_ROLES="$1"
        tuning_opts='yes'
        ;;
      --profile)
        _need_value "$1" "${2:-}"
        shift
        ST_CLI_ROLES="$(roles_from_profile "$1")" ||
          _usage_error "Invalid --profile '${1}' (general|vpn-node|wireguard|panel|relay|full)."
        ST_CLI_ROLES="${ST_CLI_ROLES// /,}"
        tuning_opts='yes'
        ;;
      --tier)
        _need_value "$1" "${2:-}"
        shift
        ST_CLI_TIER="${1^^}"
        [[ $ST_CLI_TIER =~ ^(S|M|L|XL)$ ]] || _usage_error "Invalid --tier '${1}' (S|M|L|XL)."
        tuning_opts='yes'
        ;;
      --users)
        _need_value "$1" "${2:-}"
        shift
        [[ $1 =~ ^[0-9]+$ ]] || _usage_error "Invalid --users '${1}' (expected a number)."
        ST_CLI_USERS="$1"
        tuning_opts='yes'
        ;;
      --dns)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_DNS="$1"
        tuning_opts='yes'
        ;;
      --no-swap) ST_AUTO_SWAP=0 tuning_opts='yes' ;;
      --no-limits) ST_AUTO_LIMITS=0 tuning_opts='yes' ;;
      --no-extras) ST_AUTO_EXTRAS=0 tuning_opts='yes' ;;
      --no-perf) ST_AUTO_PERF=0 tuning_opts='yes' ;;
      --no-mss) ST_AUTO_MSS=0 tuning_opts='yes' ;;
      --no-docker) ST_AUTO_DOCKER=0 tuning_opts='yes' ;;
      --no-install) ST_OPT_NO_INSTALL=1 ;;
      --json) ST_OPT_JSON=1 ;;
      --no-color) ST_OPT_NO_COLOR=1 ;;
      --debug) ST_OPT_DEBUG=1 ;;
      *)
        printf 'Unknown option: %s\n\n' "$1" >&2
        usage >&2
        exit 2
        ;;
    esac
    shift
  done

  # Tuning options only mean something for a planning run; silently ignoring
  # them would hide a typo in a provisioning script.
  if [[ -n $tuning_opts && $action != auto && $action != dryrun ]]; then
    _usage_error 'Options like --role/--tier/--users/--dns require --auto or --dry-run.'
  fi

  ui_detect_terminal
  require_root
  log_init
  state_init
  config_load
  log_info "${ST_NAME} v${ST_VERSION} started (run ${ST_RUN_ID}, action=${action})"

  local kv
  for kv in "${sets[@]-}"; do
    [[ -n $kv ]] && config_set_cli "$kv"
  done

  case "$action" in
    set) : ;;
    settings)
      ST_OPT_BATCH=1
      ui_title "Settings (${ST_CONFIG_FILE})"
      config_print
      ;;
    status)
      ST_OPT_BATCH=1
      facts_collect
      show_status
      ;;
    rollback)
      ST_OPT_BATCH=1
      rollback_latest || st_escalate_exit $?
      ;;
    rollback_original)
      ST_OPT_BATCH=1
      rollback_original || st_escalate_exit $?
      ;;
    auto)
      ST_OPT_BATCH=1
      auto_optimize
      ;;
    dryrun)
      ST_OPT_BATCH=1
      ST_DRY_RUN=1
      dry_run_optimize
      ;;
    diagnose)
      ST_OPT_BATCH=1
      diagnose_network || st_escalate_exit 3
      ;;
    verify)
      ST_OPT_BATCH=1
      facts_collect
      doctor_run || st_escalate_exit $?
      ;;
    report)
      ST_OPT_BATCH=1
      facts_collect
      roles_detect
      tools_report
      ;;
    ipv6)
      ST_OPT_BATCH=1
      ipv6_cli "$ST_CLI_IPV6" || st_escalate_exit $?
      ;;
    speedtest)
      ST_OPT_BATCH=1
      tools_speedtest_cli || st_escalate_exit 1
      ;;
    install)
      ST_OPT_BATCH=1
      st_self_install || st_escalate_exit 1
      ;;
    update)
      ST_OPT_BATCH=1
      st_self_update || st_escalate_exit 1
      ;;
    menu)
      main_menu
      ;;
  esac

  # ST_EXIT_CODE deliberately carries 1 or 3, so the ERR trap is cleared
  # first — otherwise this `return` looks like an unhandled failure.
  trap - ERR
  log_info "${ST_NAME} finished (run ${ST_RUN_ID}, exit=${ST_EXIT_CODE})"
  return "$ST_EXIT_CODE"
}

# Library mode for tests: `ST_SOURCE_ONLY=1 source dist/server-tools.sh`
# loads every function without running anything.
if [[ ${ST_SOURCE_ONLY:-0} != 1 ]]; then
  main "$@"
fi
